Class Counter
  Define valor As Integer;

  Method Constructor()
    This.valor <- 0;
  EndMethod

  Method Increment()
    This.valor <- This.valor + 1;
  EndMethod

  Method Current() As Integer
    Return This.valor;
  EndMethod
EndClass

Algorithm Count
  Define steps As Counter <- New Counter();
  steps.Increment();
  steps.Increment();
  Write steps.Current();
EndAlgorithm

Class Machine
  Define stock, collected, price As Integer;

  Method Constructor(cans As Integer)
    This.stock <- cans;
    This.collected <- 0;
    This.price <- 3;
  EndMethod

  Method Sell() As Boolean
    If This.stock = 0 Then
      Return False;
    EndIf
    This.stock <- This.stock - 1;
    This.collected <- This.collected + This.price;
    Return True;
  EndMethod

  Method Status() As String
    Return toText(This.stock) + " cans, " + toText(This.collected) + " pesos";
  EndMethod
EndClass

Algorithm Kiosk
  Define machineOne As Machine <- New Machine(10);
  Define machineTwo As Machine <- New Machine(10);
  Write machineOne.Sell(), " ", machineOne.Sell(), " ", machineTwo.Sell();
  Write "Machine 1: ", machineOne.Status();
  Write "Machine 2: ", machineTwo.Status();
EndAlgorithm

Class Machine
  Define stock, collected, price As Integer;

  Method Constructor(cans As Integer)
    This.stock <- cans;
    This.collected <- 0;
    This.price <- 3;
  EndMethod

  Method Sell() As Boolean
    If This.stock = 0 Then
      Return False;
    EndIf
    This.stock <- This.stock - 1;
    This.collected <- This.collected + This.price;
    Return True;
  EndMethod
EndClass

Algorithm Empty
  Define machine As Machine <- New Machine(0);
  Write machine.Sell(), " ", machine.stock, " ", machine.collected;
EndAlgorithm
